  "check_code": "import hashlib
import re
import sqlite3
from datetime import datetime
from pathlib import Path

from docx import Document


TARGET_ID = "CP24-SABP-BANK-ONLY"
EXPECTED_BANK_ROW = {
    "contract_population_id": TARGET_ID,
    "survey_id": "NHS_SS_2024_SABP",
    "population_id": "BANK_ONLY_ALL",
    "org_unit_id": "ORG_SABP_NHSFT",
    "employment_boundary": "in_house_bank_only",
    "shift_pattern": "mixed",
    "job_family": "All Clinical Bank",
    "invited_count": 276,
    "completed_count": 143,
    "active_worker_count": 300,
    "snapshot_date": "2024-09-23",
    "snapshot_status": "approved",
}
EXPECTED_CASE = "SBP-PO&D-SS24-METH-01"
EXPECTED_APPROVER = "Data Governance Reviewer"
EXPECTED_SUBSTANTIVE_ROWS = [
    ("CP24-SABP-ACUTE-DAY", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "OU_SABP_ACUTE_CRISIS", "substantive_contract", "day", "Registered Nursing", 365, 218, 382, "2024-09-18", "approved"),
    ("CP24-SABP-ACUTE-NIGHT", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "OU_SABP_ACUTE_CRISIS", "substantive_contract", "night", "Registered Nursing", 386, 234, 403, "2024-09-18", "approved"),
    ("CP24-SABP-ACUTE-ROT", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "OU_SABP_ACUTE_CRISIS", "substantive_contract", "rotating", "Healthcare Support Worker", 512, 319, 536, "2024-09-18", "approved"),
    ("CP24-SABP-ADULT-DAY", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "OU_SABP_ADULT_CMHT", "substantive_contract", "day", "Allied Health Professional", 427, 258, 449, "2024-09-18", "approved"),
    ("CP24-SABP-ADULT-MIX", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "OU_SABP_ADULT_CMHT", "substantive_contract", "mixed", "Medical and Dental", 471, 289, 486, "2024-09-18", "approved"),
    ("CP24-SABP-CFHS-DAY", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "OU_SABP_CHILD_FAMILY", "substantive_contract", "day", "Psychological Professions", 298, 176, 313, "2024-09-18", "approved"),
    ("POP_SUBSTANTIVE_CONTRACT_2024", "NHS_SS_2024_SABP", "SUBSTANTIVE_ALL", "ORG_SABP_NHSFT", "substantive_contract", "flexible", "Administrative and Clerical", 585, 363, 611, "2024-09-18", "approved"),
]
TECHNICAL_DOC = Path("01_原始依据") / "SurreyBorders_2024NHS员工调查_技术口径与来源索引.docx"
ACTION_DOC = Path("04_行动闭环") / "SurreyBorders_2025Q1员工体验改进_行动计划与检查表.docx"
SOURCE_HASHES = {
    TECHNICAL_DOC: "0ace35991e2b86b6441f075380bd0be38780d3b04c1f2d1c5d3292886e0bedf4",
    ACTION_DOC: "06f4bdb6cdc9b89af334c42909ceda720c1e44ee311f5495184484754aa8344d",
}


def _db_path(ws):
    return Path(ws).resolve().parent / "system" / "nhs_esr_workforce" / "state.db"


def _baseline_db_path(ws):
    return Path(ws).resolve().parent / "system" / "nhs_esr_workforce" / "state.db.pinned_backup"


def _norm(value):
    return re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", str(value).lower())


def _docx_text(path):
    document = Document(path)
    parts = [paragraph.text for paragraph in document.paragraphs]
    for table in document.tables:
        for row in table.rows:
            parts.extend(cell.text for cell in row.cells)
    return "\n".join(parts)


def _receipt_population_rows(path):
    document = Document(path)
    population_rows = {}
    for table in document.tables:
        if not table.rows:
            continue
        headers = [_norm(cell.text) for cell in table.rows[0].cells]
        column_map = {}
        for index, header in enumerate(headers):
            if any(token in header for token in ("人口边界", "populationboundary", "workforce")):
                column_map["boundary"] = index
            elif any(token in header for token in ("活跃", "active")):
                column_map["active"] = index
            elif any(token in header for token in ("邀请", "invited")):
                column_map["invited"] = index
            elif any(token in header for token in ("完成", "completed", "答卷")):
                column_map["completed"] = index
            elif any(token in header for token in ("快照日期", "snapshotdate")):
                column_map["date"] = index
        if not {"boundary", "invited", "completed"}.issubset(column_map):
            continue
        for row in table.rows[1:]:
            cells = [cell.text.strip() for cell in row.cells]
            boundary = _norm(cells[column_map["boundary"]])
            if boundary:
                population_rows[boundary] = {
                    key: cells[index] for key, index in column_map.items()
                }
    return population_rows


def _as_int(value):
    digits = re.sub(r"[^0-9-]", "", str(value))
    return int(digits) if digits else None


def _has_labeled_number(text, labels, expected):
    compact = re.sub(r"\s+", " ", text)
    number = rf"(?<!\d){expected:,}(?!\d)|(?<!\d){expected}(?!\d)"
    for label in labels:
        pattern_a = rf"{label}.{{0,28}}(?:{number})"
        pattern_b = rf"(?:{number}).{{0,28}}{label}"
        if re.search(pattern_a, compact, re.I) or re.search(pattern_b, compact, re.I):
            return True
    return False


def _has_snapshot_date(text):
    date_patterns = (
        r"2024[-/.年]\s*0?9[-/.月]\s*23(?:日)?",
        r"23\s+(?:September|Sep)\s+2024",
        r"(?:September|Sep)\s+23,?\s+2024",
    )
    return any(re.search(pattern, text, re.I) for pattern in date_patterns)


def check_bank_snapshot_and_audit_post_state(ws):
    database = _db_path(ws)
    if not database.exists():
        return {"score": 0, "detail": "NHS ESR Workforce Master database is missing"}
    with sqlite3.connect(database) as connection:
        connection.row_factory = sqlite3.Row
        row = connection.execute(
            "SELECT * FROM contract_populations WHERE contract_population_id = ?",
            (TARGET_ID,),
        ).fetchone()
        audit_table = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'contract_population_approval_audit'"
        ).fetchone()
        audit = None
        if audit_table:
            audit = connection.execute(
                "SELECT contract_population_id, approval_case_id, approved_by, approved_at "
                "FROM contract_population_approval_audit WHERE contract_population_id = ?",
                (TARGET_ID,),
            ).fetchone()
    if row is None:
        return {"score": 0, "detail": "Target bank-only snapshot is missing"}
    mismatches = {
        key: {"expected": expected, "actual": row[key]}
        for key, expected in EXPECTED_BANK_ROW.items()
        if row[key] != expected
    }
    if mismatches:
        return {"score": 0, "detail": f"Target snapshot mismatch: {mismatches}"}
    if audit is None:
        return {"score": 0, "detail": "Approval audit for the target snapshot is missing"}
    if _norm(audit["approval_case_id"]) != _norm(EXPECTED_CASE):
        return {"score": 0, "detail": f"Unexpected approval case: {audit['approval_case_id']}"}
    if _norm(audit["approved_by"]) != _norm(EXPECTED_APPROVER):
        return {"score": 0, "detail": f"Unexpected approver role: {audit['approved_by']}"}
    try:
        datetime.fromisoformat(str(audit["approved_at"]).replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return {"score": 0, "detail": "Approval timestamp is missing or invalid"}
    return {"score": 1, "detail": "Bank-only snapshot and controlled approval audit are correct"}


def check_population_boundary_receipt(ws):
    folder = Path(ws) / "04_行动闭环"
    candidates = [
        path
        for path in folder.glob("*.docx")
        if "人口" in path.name and "边界" in path.name and "回执" in path.name
    ]
    if len(candidates) != 1:
        return {"score": 0, "detail": f"Expected one Word population-boundary receipt, found {len(candidates)}"}
    try:
        text = _docx_text(candidates[0])
        population_rows = _receipt_population_rows(candidates[0])
    except Exception as exc:
        return {"score": 0, "detail": f"Receipt cannot be opened: {exc}"}
    normalized = _norm(text)
    required_text = {
        "organisation": "Surrey and Borders Partnership NHS Foundation Trust",
        "survey": "2024 NHS Staff Survey",
        "bank boundary": "bank-only",
        "approval case": EXPECTED_CASE,
        "approver": EXPECTED_APPROVER,
    }
    missing_text = [name for name, value in required_text.items() if _norm(value) not in normalized]
    if not ("正式合同员工" in normalized or "substantiveworkforce" in normalized or "substantivecontract" in normalized):
        missing_text.append("formal boundary")

    # Accept either a tabular receipt or clearly labelled prose/rows. The task
    # requires the values and their population labels, not one fixed layout.
    def _has_boundary_number(boundaries, labels, expected):
        number = re.compile(rf"(?<!\d)(?:{expected:,}|{expected})(?!\d)")
        compact = re.sub(r"\s+", " ", text)
        for match in number.finditer(compact):
            context = _norm(compact[max(0, match.start() - 320):match.end() + 320])
            if any(_norm(boundary) in context for boundary in boundaries) and any(_norm(label) in context for label in labels):
                return True
        return False

    bank_row = next((row for boundary, row in population_rows.items() if "bankonly" in boundary), {})
    substantive_row = next(
        (row for boundary, row in population_rows.items() if "正式合同员工" in boundary or "substantive" in boundary),
        {},
    )
    checks = {
        "bank active 300": _as_int(bank_row.get("active")) == 300 or _has_boundary_number(
            ("bank-only", "bankonly", "in_house_bank_only", "bank workers"),
            ("活跃", "active_worker_count", "active workers", "active"), 300),
        "bank invited 276": _as_int(bank_row.get("invited")) == 276 or _has_boundary_number(
            ("bank-only", "bankonly", "in_house_bank_only", "bank workers"),
            ("邀请", "邀请数", "invited_count", "invited"), 276),
        "bank completed 143": _as_int(bank_row.get("completed")) == 143 or _has_boundary_number(
            ("bank-only", "bankonly", "in_house_bank_only", "bank workers"),
            ("完成", "完成人数", "completed_count", "completed", "答卷"), 143),
        "substantive invited 3044": _as_int(substantive_row.get("invited")) == 3044 or _has_boundary_number(
            ("正式合同员工", "substantive workforce", "substantive_contract", "formal contract"),
            ("邀请", "邀请数", "invited_count", "invited"), 3044),
        "substantive completed 1857": _as_int(substantive_row.get("completed")) == 1857 or _has_boundary_number(
            ("正式合同员工", "substantive workforce", "substantive_contract", "formal contract"),
            ("完成", "完成人数", "completed_count", "completed", "答卷"), 1857),
        "snapshot date": _has_snapshot_date(bank_row.get("date", "")) or _has_snapshot_date(text),
        "separate reporting": (
            any(token in normalized for token in ("分开报告", "分别报告", "单独报告", "separatelyreported"))
            and any(token in normalized for token in ("方法", "method", "methodology"))
            and any(token in normalized for token in ("题目", "题项", "question"))
            and any(token in normalized for token in (
                "人群构成", "人口构成", "人群边界", "人群不同", "独立人群", "工作方式构成",
                "workforcecomposition", "populationcomposition", "workforceboundary", "populationboundary",
                "employmentboundary", "雇佣关系",
            ))
        ),
    }
    failures = [name for name, ok in checks.items() if not ok]
    if missing_text or failures:
        return {"score": 0, "detail": f"Receipt missing text={missing_text}, checks={failures}"}
    return {"score": 1, "detail": f"Receipt is valid: {candidates[0].name}"}

def check_substantive_snapshots_unchanged(ws):
    current_path = _db_path(ws)
    if not current_path.exists():
        return {"score": 0, "detail": "Current ESR database is missing"}
    query = (
        "SELECT * FROM contract_populations WHERE survey_id = 'NHS_SS_2024_SABP' "
        "AND employment_boundary = 'substantive_contract' "
        "ORDER BY contract_population_id"
    )
    with sqlite3.connect(current_path) as current:
        current_rows = current.execute(query).fetchall()
    if current_rows != EXPECTED_SUBSTANTIVE_ROWS:
        return {"score": 0, "detail": "At least one substantive-contract snapshot changed"}
    return {"score": 1, "detail": "All substantive-contract snapshots are unchanged"}


def check_source_documents_unchanged(ws):
    failures = []
    for relative_path, expected_hash in SOURCE_HASHES.items():
        path = Path(ws) / relative_path
        if not path.exists():
            failures.append(f"missing {relative_path}")
            continue
        actual_hash = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual_hash != expected_hash:
            failures.append(f"modified {relative_path}")
    if failures:
        return {"score": 0, "detail": "; ".join(failures)}
    return {"score": 1, "detail": "Both source documents are unchanged"}
